INSERT INTO `crs_tabledata704` VALUES ('552', '{CB4B8E01-B192-4D97-B123-1923A87CF32F}', '60', 'INHE-0066', '2017-03-07 17:51:25', '0000-00-00 00:00:00', '2017-03-10 15:51:31', 'unchecked', 'n', 'n', '', '1', 'PO#E1704/白雪704/合同评审', '', '1', '', '', '', '0', '0', '0', '');
INSERT INTO `crs_tabledata704` VALUES ('553', '{F5C192DF-92D0-4EEB-8C8B-FF0EF39518F2}', '60', 'INHE-0088', '2017-03-08 14:50:53', '0000-00-00 00:00:00', '2017-03-17 09:13:31', 'unchecked', 'n', 'n', '', '1', 'INHESC2017030201/DPM701/合同评审', 'DPM701', '1', '三相四线非直接接入式智能电表', 'DTZ1513', '个', '92', '170', '15640', '1.0 总要求\r\r\n1.1范围: 三相CT表，用于中压计量系统中用户账单，电量处理和负荷曲线\r\r\n电表功能：有功电能计量，无功电能计量\r\r\n处理单元：能够执行电能的加减和需量值计算；\r\r\n          能够执行电能费率和最大需量计算包括个人需量费率；\r\r\n          能够处理最小4个脉冲输入，互相独立；\r\r\n          有通讯设施。\r\r\n\r\r\n1.2操作条件 : 电表用于用户账单，使用交流电，有功、无功电能，带以下操作条件：\r\r\n         基本电流：5A\r\r\n         电压： 3*110/√3V 相线到零线\r\r\n         频率： 50Hz\r\r\n         正向顺序： R-Y-B\r\r\n\r\r\n1.3 精度等级： 符合IEC-62053-22和IEC-62053-23\r\r\n         有功测量0.5级， 无功测量2级\r\r\n         提供全套型式测试证书\r\r\n         电表应是3元件类型如三相四线， 或2元件类型如三相三线\r\r\n1.4 基本功能： 四象限电能测量（有功和无功）\r\r\n               电能脉冲通过输出传输到一个处理单元（如有要求）\r\r\n               任何指定的重要值都可编程\r\r\n    处理单元功能：通过输入接触恢复电能脉冲来累计电能读数，执行电能加减和需量值计算；\r\r\n                  电能费率化和最大需量计算包括个人需量费率；\r\r\n                  至少4个费率，使用内部时钟和日历；\r\r\n                  远程抄读通讯设施\r\r\n1.5 标准： IEC-62052-11, IEC-62053-22, IEC-62053-23, IEC-62056-21, IEC-60338, IEC-60514, \r\r\nBS 5685\r\r\n1.6 气候条件： 热带地区，环境温度21-40°C, 湿热气候，湿度变化迅速频繁，相对湿度45%-85%， 雷电频率高，雷雨活动水平150-400\r\r\n\r\r\n2.0 条文阐释\r\r\n2.1 条文定义 a) 延伸型端盖：可独立于表壳封闭；能围住端座，包括凸出于端座的合适长度的外部导体。\r\r\nb) 表常数： 表达每千瓦时下，电表注册电能和相应测试脉冲输出数量的关系。\r\r\n\r\r\n3.0 物理性要求\r\r\n3.1 总构造： 构造完整，耐高温，面板安装。所有机械和电子元件应保证寿命，并防尘。\r\r\n             设计构造要保证人员安全，防电击，防过温影响和火势蔓延，防腐蚀，耐湿热。IP51\r\r\n3.2 绝缘材料： 防吸湿\r\r\n3.3 温度上升： 电流和电压元件能够携带全过载电流和过压，没有过度的温度上升和电能损耗。\r\r\n3.4 表底和表盖： 非金属，绝缘，非吸湿，非可燃，防尘，高温不变形，阻燃。\r\r\n                 表底和端子元件分开，接口圆滑，保证铅封贴纸不损坏不变形，贴纸35mm, 贴在至少表盖的10mm 和表底的25mm的接口处。不移动端盖的情况下不能移开表盖。\r\r\n3.5 端子和端子盖： 端子要允许从底部进入的实心和绞合铜导体的连接。\r\r\n                  零线连接端子要符合TNB 使用快速连接体的测试设置；\r\r\n                  延伸型端子盖，端子盖要包围端子和导体固定螺丝，以及连接在端座的绝缘外部线缆。\r\r\n                  端子盖非金属，绝缘，非吸湿，非可燃，防尘，高温不变形，阻燃。\r\r\n3.6 铅封设备： 表盖要独立于端子座铅封；可铅封端子座和延伸型端盖；表盖，重置按钮可铅封，以防窃电；铅封设备安全，结实，不易损坏。\r\r\n3.7 铭牌： 铭牌内容：\r\r\n          制造商名称，制造地点；\r\r\n          型号/类型；\r\r\n          分配系统，如三相四线；\r\r\n          频率；\r\r\n          表常数；\r\r\n          精度等级；\r\r\n          所有者名称：Property of Sabah Electricity Sdn Bhd\r\r\n        SESB提供序列号（表号）；\r\r\n        制造年份和发货年份；\r\r\n        显示识别码\r\r\n3.8 接线图和端子标识：每个端子接线要标有对应的number以便识别\r\r\n                     电压端子应刻有字母R,Y,B 或 R, S, T，或根据接线图标识\r\r\n3.9 序列号： 最终包含制造年份的序列号安排应经SESB同意，序列号应是黑色的SESB序列号。\r\r\n            制造商序列号最少8个字母，包括1个代表制造商，1个代表发货年份，1个代表表型，5个表示序列号，如A6100001；\r\r\n            序列号应是条形码标准，如Code 39, UPC A, UPC E, EAN 13, EAN 8, 2-5交叉，CODABAR和Code 128；\r\r\n            最终条形码序列号应在计量单元存储计度器电子存储，以便恢复数据；\r\r\n            发货前，铭牌最终设计要提交给SESB审核批准。\r\r\n4.0技术要求\r\r\n4.1概述 所有电能测试（kWh和kVarh）和功能比如最大需量计算，费率，计时和通信将提供给记录系统。\r\r\n4.2网络 电表是三相四线或三相三线，取决于日程表。\r\r\n        频率50Hz\r\r\n        在正向序列操作 i.e ‘R-Y-B’\r\r\n4.3电流和电压 基本电流5A，由电流互感器操作\r\r\n火线到零线的电流是110/√3V从电压互感器第二面获得。电表可以操作从一相到零线的连接。\r\r\n电表首先可以编程电压和电流比率。\r\r\n4.4精度 0.5级，符合IEC62053-22标准。至少满足2级，符合IEC62053-23.需要提供关于这点的经认可的实验室的测试证书。\r\r\n有单独的精度测试IED测试kWh和kVarh。LED灯必须有足够的频率来得到好的测试目的的解决方案--样品一样要求。\r\r\n4.5存储 所有程序化的表计单元和测量值（现在值和月度重置值）都储存在不易失的存储器里（比如EEPROM）以至于不管有电力中断或在储存过程都不会有数据损失。\r\r\n低压500msec的电力中断不会影响电表自己的功能。\r\r\n有一个寄存器记录电力供应中断时期的发生时间和数据。\r\r\n4.6电能方向 有一个测量电能方向的指示，i.e.电能电流值输入/输出或者象限位置。\r\r\n4.7电表输出连接 电表至少有四个可配置的输出连接来在需要时把电能脉冲转到外部装置。\r\r\n输出连接设计得是最可靠的类型并且证实有很长的寿命。连接可以是自由弹跳的，有潜能的并能最多承受120V A.C.。有连接保护。\r\r\n脉冲输出值重量应该和电表尺寸相称。\r\r\n4.8 输入连接 处理单元最少有4个独立的和可配置的输入脉冲连接，以恢复有功和无功电能。\r\r\n输入脉冲连接要有可靠的设计和较长的寿命，耐受120V交流电压， 此连接工作电压最少10V，要有内置连接保护。输入脉冲值应当根据电表与之连接的尺寸按比例可编程。\r\r\n4.9 加减功能 处理单元能从至少4个指定的输入脉冲执行电能的加减和需量值，所加的值能够根据5.4-5.6项进一步处理。\r\r\n4.10 辅助电源 处理单元要有一个110/√3V 交流，相线到零线的辅助电源，以保证计量单元在停电时继续工作。\r\r\n4.11 显示  LCD显示，字符规格如下表，背光显示，显示要能够表明在用哪一个费率\r\r\n	累计计度器	月重置计度器（实际耗能）	Register multiplying factor(内部)\r\r\nKWh	9个字符	8个字符	1\r\r\nKVArh	9个字符	8个字符	1\r\r\nKW		5个字符	1\r\r\n注：不允许内部使用10倍相乘（如：*10， 或*100）\r\r\n4.12 后备电池  计量单元要有后备电池保证停电时能保持日期和时间。\r\r\n               电池至少10年寿命，操作容量1年。\r\r\n               电池不能连接到电表电路上，以免运输和存储过程中电池损耗。\r\r\n               电池在市场上可买得到。\r\r\n4.13 时间时钟  处理单元要有一个石英控制时钟，功能如下：\r\r\n               时，分，秒\r\r\n               日，月，年\r\r\n               自动闰年\r\r\n       允许的时间偏差不超过6 P.P.M\r\r\n4.14 光电接口  计量单元有光电通讯接口，以便用手持或便携式设备编程和抄读存储数据\r\r\n4.15 通讯接口  如RS232接口，目的：\r\r\n               通过PC直接与计量单元通讯；\r\r\n               远程抄读设备—恢复存储计量单元参数，事件记录，警报，电能值，负荷曲线，月重置值等，或者通过PSTN/PLC/无线系统，使用相关机构认证的解调器，或者通过光纤通讯系统，到达SESB的远程抄表站。\r\r\n               符合IEC62056-21通过手持终端恢复存储参数和月重置值.\r\r\n4.16 同步性  同步输出和输入：\r\r\n             外部时间同步性和\r\r\n             主计量单元和检查计量单元之间的同步性\r\r\n        每个整合期结束时，要能够通过合适的安全等级，远程同步计量单元系统时间。\r\r\n4.17 按钮  读数按钮：所有选择的信息包括重置值应当一个个显示，\r\r\n           手动重置按钮： 用此按钮，账单周期关闭，所有必要信息转移到存储器的相应计度器中；此按钮独立铅封；按钮结实可靠。\r\r\n4.18 防磁  任何小于500MT+_10%磁影响不会导致超过+_4.0%的误差；\r\r\n           任何超过500MT+_10%磁影响，电表应当转换到最大负载条件，激活警报。只要磁影响存在，就应保持最大负载条件，磁影响消除，恢复正常工作条件。警报重置只能通过软件方式实现，经过光电通讯接口或RS接口。\r\r\n           额定电压，基本电流，和总功率因素条件下进行测试。\r\r\n4.19 不规则监测  电表要能够检测和记录“计量不规则性”，包括但不限于以下：\r\r\n                 反向电能；不正确的相位旋转；相电压不存在；开表盖；磁窃电；负载不平衡（可选的不平衡百分比）；电池失效；时钟失效；存储器失效\r\r\n         能够提供其他的不规则检测事件的投标人有优势，如：旁路计量\r\r\n5.0 计量单元软件  \r\r\n5.1 软件  软件使用最新的Windows版本，至少提供2套软件：\r\r\n          计量单元配置软件以用于编程\r\r\n          提取抄读，负荷曲线，警报和电表问题解决的软件—完整的三相相量图，电表电压和电流的波形。\r\r\n    以上软件，每个都至少要有8个用户许可证，软件使用无年费和维修费，免费提供任何升级更新版本。\r\r\n5.2 安全机制-硬件  计量单元应当有硬件锁来防止未经授权接触计量单元配置参数。硬件锁封在计量单元盖内。\r\r\n5.3安全机制-软件  软件要有以下安全机制来防止未经授权使用电脑编程软件（至少4个安全等级）\r\r\n  \r\r\n等级1—管理员	读，写。修改所有配置和用户设置\r\r\n等级2—行政人员	读，写。修改所有配置\r\r\n等级3—技术人员	读，写计量单元\r\r\n等级4—抄表员	读计量单元\r\r\n5.4 费率处理  计量单元能够在4个相互独立的电能费率和4个需量费率下编程和显示KWh, KVArh, KW, KVAR。\r\r\n              显示值应当是目前运行值和月重置值。\r\r\n5.5 最大需量  一个账单周期内的最大需量值应当随他们的发生日期和时间一块显示和存储。需量整合期可从5-60分钟编程。\r\r\n              计算的最大需量应是平均需量或滑差需量（最小6个滑差区间）\r\r\n5.6 存储值  重置值（账单周期末）后，转移到另一个分开的计度器存储。\r\r\n           存储值应当: 每个费率下的实际有功和无功耗能，\r\r\n                       每个费率下的实际有功和无功最大需量，（带日期和时间）\r\r\n           对于账单周期，其中的值应当包括所有费率计度器的总累计值，如所有月重置值总和；容量要足够存储至少6个重置值。\r\r\n');
INSERT INTO `crs_tabledata704` VALUES ('554', '{6FBB1EDB-27FD-41C3-8577-C83C353DD07E}', '60', 'INHE-0088', '2017-03-08 18:59:45', '0000-00-00 00:00:00', '2017-03-14 08:49:11', 'unchecked', 'n', 'n', '', '1', 'INHESC2017021801/ST20703/合同评审', 'ST20703', '1', '', '', '', null, null, '0', '');
