INSERT INTO `crs_tabledata704` VALUES ('1238', '{85A326FC-2AE6-44DA-B50F-223201C92AA4}', '61', 'INHE-0776', '2019-03-11 08:37:32', '0000-00-00 00:00:00', '2019-03-14 16:42:40', 'unchecked', 'n', 'n', '', '2', 'PLD01/INHESC2019011601/合同评审', '', '2', '三相四线直接接入式可更换通信模块智能电表（PLC通信模块）', '3X220/380V,5A /100A,60Hz,1000 imp/kWh', '台', '9', '110', '990', '电压：3x220/380V，频率：60HZ, 负荷曲线,PLC-FSK模块。需有窃电检测功能。PLC-FSK模块，需每间隔30或60分钟收集数据，LCD显示屏数字位数需大于7位，（receptor）通信模块的灵敏度最少为130dBm. 负荷曲线每条通道应储存时间超过35天，生产过程需满足IEC 562053-21 e和IEC 62053-23。IP54,湿度：95%不凝结');
